const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readNextString() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        const start = offset;
        while (offset < buffer.length && buffer[offset] > 32) {
            offset++;
        }
        return buffer.toString('utf8', start, offset);
    }

    const nStr = readNextString();
    if (!nStr) return;
    const n = parseInt(nStr, 10);
    const x1 = BigInt(readNextString());
    const x2 = BigInt(readNextString());

    const points = new Array(n);
    const vList = new Array(n);

    for (let i = 0; i < n; i++) {
        const a = BigInt(readNextString());
        const b = BigInt(readNextString());
        const u = a * x1 + b;
        const v = a * x2 + b;
        points[i] = { u, v };
        vList[i] = v;
    }

    // Coordenadas de v para compressão
    vList.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    let uniqueVCount = 0;
    for (let i = 0; i < n; i++) {
        if (i === 0 || vList[i] !== vList[i - 1]) {
            vList[uniqueVCount++] = vList[i];
        }
    }
    vList.length = uniqueVCount;

    function getVIndex(val) {
        let low = 0, high = uniqueVCount - 1;
        while (low <= high) {
            const mid = (low + high) >> 1;
            if (vList[mid] === val) return mid + 1; // 1-based index
            if (vList[mid] < val) low = mid + 1;
            else high = mid - 1;
        }
        return low + 1;
    }

    for (let i = 0; i < n; i++) {
        points[i].vRank = getVIndex(points[i].v);
    }

    // Ordenar points por u crescente
    points.sort((p1, p2) => (p1.u < p2.u ? -1 : p1.u > p2.u ? 1 : 0));

    // Fenwick Tree (Binary Indexed Tree)
    const bit = new Int32Array(uniqueVCount + 1);

    function add(idx, val) {
        for (; idx <= uniqueVCount; idx += idx & -idx) {
            bit[idx] += val;
        }
    }

    function query(idx) {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += bit[idx];
        }
        return sum;
    }

    let concordantPairs = 0n;

    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && points[j].u === points[i].u) {
            j++;
        }

        // Consultar para cada ponto no grupo de mesmo u
        for (let k = i; k < j; k++) {
            // queremos pontos anteriores com v < points[k].v, logo vRank < points[k].vRank
            concordantPairs += BigInt(query(points[k].vRank - 1));
        }

        // Inserir os pontos do grupo na Fenwick Tree
        for (let k = i; k < j; k++) {
            add(points[k].vRank, 1);
        }

        i = j;
    }

    const totalPairs = (BigInt(n) * BigInt(n - 1)) / 2n;
    const ans = totalPairs - concordantPairs;

    console.log(ans.toString());
}

solve();
